summary_script_v2 = '''import openpyxl

wb = openpyxl.load_workbook("testbed/data/travel_expenses.xlsx", data_only=True)

all_rows = []
for sheet_name in wb.sheetnames:
    ws = wb[sheet_name]
    headers = None
    for i, row in enumerate(ws.iter_rows(values_only=True)):
        if i == 0:
            headers = [str(c).strip() if c is not None else f"col_{j}" for j, c in enumerate(row)]
        else:
            record = {headers[j]: c for j, c in enumerate(row)}
            record["_sheet"] = sheet_name
            all_rows.append(record)

if not all_rows:
    print("No data found.")
    exit()

keys = [k for k in all_rows[0].keys() if k != "_sheet"]
print("Columns:", keys)

# Detect key columns
amount_col = None
for k in keys:
    if any(w in k.lower() for w in ["amount", "cost", "price", "total", "expense", "spend", "fare", "charge"]):
        amount_col = k
        break

cat_col = None
for k in keys:
    if any(w in k.lower() for w in ["category", "type", "class", "kind"]):
        cat_col = k
        break

status_col = None
for k in keys:
    if any(w in k.lower() for w in ["status", "booking", "confirmed", "state"]):
        status_col = k
        break

date_col = None
for k in keys:
    if any(w in k.lower() for w in ["date"]):
        date_col = k
        break

desc_col = None
for k in keys:
    if any(w in k.lower() for w in ["description", "destination", "trip", "detail", "name", "vendor", "merchant", "item"]):
        desc_col = k
        break

print(f"Detected => amount: {amount_col}, category: {cat_col}, status: {status_col}, date: {date_col}, desc: {desc_col}")

# Compute summary
total_spend = 0
category_spend = {}
status_counts = {}
confirmed_bookings = []
confirmed_spend = 0

for row in all_rows:
    amt = 0
    if amount_col and row.get(amount_col) is not None:
        try:
            amt = float(row[amount_col])
        except (ValueError, TypeError):
            amt = 0
    total_spend += amt

    cat = str(row.get(cat_col, "Unknown")) if cat_col else row.get("_sheet", "Unknown")
    category_spend[cat] = category_spend.get(cat, 0) + amt

    status = str(row.get(status_col, "N/A")) if status_col else "N/A"
    status_counts[status] = status_counts.get(status, 0) + 1

    if status_col and status.lower() in ["confirmed", "booked", "approved", "yes"]:
        confirmed_bookings.append(row)
        confirmed_spend += amt

sep = "=" * 60
print(f"\\n{sep}")
print("TRAVEL EXPENSES SUMMARY (from testbed/data/travel_expenses.xlsx)")
print(sep)
print(f"Total expense entries: {len(all_rows)}")
print(f"Total spend: ${total_spend:,.2f}")

print(f"\\n--- Spend by Category ---")
for cat, amt in sorted(category_spend.items(), key=lambda x: -x[1]):
    pct = (amt / total_spend * 100) if total_spend else 0
    print(f"  {cat}: ${amt:,.2f} ({pct:.1f}%)")

if status_col:
    print(f"\\n--- Booking Status Breakdown ---")
    for status, count in sorted(status_counts.items(), key=lambda x: -x[1]):
        print(f"  {status}: {count}")

    print(f"\\n--- Confirmed Bookings ({len(confirmed_bookings)}) | Total: ${confirmed_spend:,.2f} ---")
    for b in confirmed_bookings:
        parts = []
        if desc_col and b.get(desc_col):
            parts.append(str(b[desc_col]))
        if date_col and b.get(date_col):
            parts.append(str(b[date_col]))
        if cat_col and b.get(cat_col):
            parts.append(str(b[cat_col]))
        if amount_col and b.get(amount_col) is not None:
            parts.append(f"${float(b[amount_col]):,.2f}")
        if status_col and b.get(status_col):
            parts.append(f"[{b[status_col]}]")
        print(f"  - {' | '.join(parts)}")
else:
    print("\\nNo status column detected — listing all entries:")
    for b in all_rows:
        parts = []
        for k in keys:
            if b.get(k) is not None:
                parts.append(f"{k}: {b[k]}")
        print(f"  - {' | '.join(parts)}")

print(f"\\n{sep}")
'''
await write_file("./summary_travel_v2.py", summary_script_v2)

summary_output = await run_command("python ./summary_travel_v2.py")
print(summary_output)
